const interestTerms = ['interesse', 'interessante', 'gostaria', 'vamos conversar', 'podemos conversar', 'tenho interesse'];
const budgetTerms = ['orçamento', 'orcamento', 'preço', 'preco', 'valor', 'verba', 'investimento', 'quanto custa'];
const meetingTerms = ['reunião', 'reuniao', 'call', 'conversa', 'agenda', 'agendar', 'disponibilidade', 'horário', 'horario'];
const negotiationTerms = ['proposta', 'prazo', 'escopo', 'contrato', 'condições', 'condicoes', 'ajuste', 'negociar', 'fechar'];
const refusalTerms = ['não tenho interesse', 'nao tenho interesse', 'não queremos', 'nao queremos', 'já resolvemos', 'ja resolvemos', 'recusar', 'recusado'];
const optOutTerms = ['não entrar em contato', 'nao entrar em contato', 'remover', 'remova', 'não quero receber', 'nao quero receber', 'unsubscribe', 'stop', 'pare de enviar'];
const getText = (item) => [item.subject, item.snippet, item.textPlain, item.text, item.body].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR');
const hasLabel = (item, label) => Array.isArray(item.labelIds) && item.labelIds.some((value) => String(value).toUpperCase() === label);
const messages = $input.all().map((item) => item.json);
const sentThreads = new Set(messages.filter((item) => hasLabel(item, 'SENT') || String(item.from || '').toLowerCase().includes('me')).map((item) => String(item.threadId || item.thread_id || '')).filter(Boolean));
const incoming = messages.filter((item) => {
  const threadId = String(item.threadId || item.thread_id || '');
  return threadId && sentThreads.has(threadId) && !hasLabel(item, 'SENT') && !String(item.from || '').toLowerCase().includes('me');
});
return incoming.map((item) => {
  const text = getText(item);
  const matches = (terms) => terms.filter((term) => text.includes(term));
  const interest = matches(interestTerms);
  const budget = matches(budgetTerms);
  const meeting = matches(meetingTerms);
  const negotiation = matches(negotiationTerms);
  const refusal = matches(refusalTerms);
  const optOut = matches(optOutTerms);
  const categories = [];
  if (interest.length) categories.push('interesse');
  if (budget.length) categories.push('orcamento');
  if (meeting.length) categories.push('reuniao');
  if (negotiation.length) categories.push('negociacao');
  if (refusal.length) categories.push('recusa');
  if (optOut.length) categories.push('nao_contato');
  const priority = optOut.length || budget.length || meeting.length || negotiation.length ? 'alta' : categories.length ? 'media' : 'baixa';
  return { json: { source: 'gmail', thread_id: String(item.threadId || item.thread_id), message_id: String(item.id || item.messageId || ''), sender: item.from || item.sender || 'não identificado', subject: item.subject || 'sem assunto', excerpt: String(item.snippet || item.textPlain || item.text || '').replace(/\s+/g, ' ').trim().slice(0, 1000), categories, matched_terms: [...new Set([...interest, ...budget, ...meeting, ...negotiation, ...refusal, ...optOut])], priority, opt_out_signal: Boolean(optOut.length), alert_title: optOut.length ? 'AÇÃO IMEDIATA: pedido de não contato' : `Resposta comercial ${priority}: ${(item.subject || 'sem assunto').slice(0, 100)}` } };
}).filter(({ json }) => json.categories.length > 0);
